// Generated by Contentrain Migrate. A page section's markdown under the page's own
// headings, with no level skipped (Lighthouse heading-order): an h3 written right under the
// page's h1 becomes an h2, an h5 under an h1 becomes an h2, each next heading goes at most one
// level deeper than the one before it, and headings keep their order relative to each other.
// The first heading's step keeps its look through `data-cr-shift`; a later heading moved to
// another step is written as an HTML heading with `data-cr-level` = the level the editor
// wrote, which keeps that look (styles/global.css) — plain text only: one with inline markup
// stays a markdown heading at its new level.
// On a modern order an h1–h3 is also written with its longest word's length (`fitHeadings`),
// so the stylesheet keeps that word on one line in the body's width.

const HEADING = /^( {0,3})(#{1,6})(?=[ \t]|$)/
const FENCE = /^ {0,3}(```|~~~)/
/** Inline markdown an HTML heading would print as it is: links, emphasis, code, a raw tag. */
const INLINE = /(^|[^\\])[[*_`<]/
const ESCAPED = /\\([!-/:-@[-`{-~])/g

/** A plain-text heading as HTML at `level`, looking like the `written` one: undefined when it carries inline markup. */
function htmlHeading(line: string, level: number, written: number): string | undefined {
  const text = line.replace(HEADING, '').replace(/[ \t]+#+[ \t]*$/, '').trim()
  if (!text || INLINE.test(text)) return undefined
  const html = text.replace(ESCAPED, '$1').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  return `<h${level} data-cr-level="${written}">${html}</h${level}>`
}

/**
 * The markdown with its headings on a whole outline under `above`, how far the first stepped up (undefined: as written),
 * and the level the first prints at (`top`, undefined: no heading), which the page's next section opens under.
 */
export function headingLevels(markdown: string | undefined, above: number): { markdown: string | undefined, shift: number | undefined, top: number | undefined } {
  if (!markdown) return { markdown, shift: undefined, top: undefined }
  const lines = markdown.split('\n')
  const at: number[] = []
  let fenced = false
  lines.forEach((line, i) => {
    if (FENCE.test(line)) fenced = !fenced
    else if (!fenced && HEADING.test(line)) at.push(i)
  })
  if (!at.length) return { markdown, shift: undefined, top: undefined }
  // The open headings, as written and as printed: a heading closes every deeper one before it.
  const open: Array<{ written: number, printed: number }> = []
  let changed = false
  let shift: number | undefined
  let firstLevel: number | undefined
  for (const i of at) {
    const written = HEADING.exec(lines[i]!)![2]!.length
    while (open.length && open[open.length - 1]!.written > written) open.pop()
    const top = open[open.length - 1]
    let printed: number
    if (top && top.written === written) { printed = top.printed; open.pop() }
    else if (top) printed = top.printed + 1
    else printed = Math.min(written, above + 1)
    printed = Math.min(6, printed)
    const first = shift === undefined
    if (first) { shift = written - printed > 0 ? written - printed : 0; firstLevel = printed }
    open.push({ written, printed })
    if (printed !== written) {
      changed = true
      // A step other than the first heading's (which the section's data-cr-shift restyles) keeps its look on its own.
      const html = !first && written - printed !== shift && htmlHeading(lines[i]!, printed, written)
      // An HTML block runs to the next blank line: one closes it so the line after stays its own paragraph.
      if (html) lines[i] = html + (lines[i + 1]?.trim() ? '\n' : '')
      else lines[i] = lines[i]!.replace(HEADING, (_, indent: string) => indent + '#'.repeat(printed))
    }
  }
  return changed ? { markdown: lines.join('\n'), shift: shift || undefined, top: firstLevel } : { markdown, shift: undefined, top: firstLevel }
}

/** An HTML heading of the page's three top levels at the start of a line, as `htmlHeading` writes it or the editor did. */
const HTML_HEADING = /^<h([1-3])((?: [a-z-]+="[^"]*")*)>([^<]*)<\/h\1>$/

/** The longest word of a heading's text, in characters (at least 1). */
const longestWord = (text: string): number => text.trim().split(/\s+/).reduce((n, w) => Math.max(n, [...w].length), 1)

/**
 * The markdown's h1–h3 written so the stylesheet can keep each one's longest word on a line (a word wider than its column
 * was broken mid-letters): an HTML heading carrying the word's length (`--cr-word`) around its text, which the
 * stylesheet sizes against the body's own width. Plain text only, as `htmlHeading`: one with inline markup stays as written.
 */
export function fitHeadings(markdown: string | undefined): string | undefined {
  if (!markdown) return markdown
  const lines = markdown.split('\n')
  let fenced = false
  lines.forEach((line, i) => {
    if (FENCE.test(line)) { fenced = !fenced; return }
    if (fenced) return
    const level = HEADING.exec(line)?.[2]?.length
    let html: string | undefined
    if (level !== undefined && level <= 3) html = htmlHeading(line, level, level)?.replace(` data-cr-level="${level}"`, '')
    else if (HTML_HEADING.test(line)) html = line
    const m = html ? HTML_HEADING.exec(html) : null
    if (!m) return
    const text = m[3]!.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
    lines[i] = `<h${m[1]}${m[2]} style="--cr-word: ${longestWord(text)}"><span data-cr-fit>${m[3]}</span></h${m[1]}>` + (level !== undefined && lines[i + 1]?.trim() ? '\n' : '')
  })
  return lines.join('\n')
}
